DROP DATABASE IF EXISTS titiktiga;
CREATE DATABASE titiktiga CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci;
USE titiktiga;
CREATE TABLE users (id CHAR(36) PRIMARY KEY, name VARCHAR(120) NOT NULL, email VARCHAR(255) NOT NULL UNIQUE, password_hash VARCHAR(255) NOT NULL DEFAULT '', role ENUM('customer','admin') NOT NULL DEFAULT 'customer', phone VARCHAR(30) DEFAULT '', email_verified_at DATETIME DEFAULT NULL, created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP, updated_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS email_verification_tokens (id CHAR(36) PRIMARY KEY, user_id CHAR(36) NOT NULL, token_hash CHAR(64) NOT NULL UNIQUE, expires_at DATETIME NOT NULL, used_at DATETIME DEFAULT NULL, created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP, INDEX(user_id), FOREIGN KEY(user_id) REFERENCES users(id) ON DELETE CASCADE);
CREATE TABLE IF NOT EXISTS password_reset_tokens (id CHAR(36) PRIMARY KEY, user_id CHAR(36) NOT NULL, token_hash CHAR(64) NOT NULL UNIQUE, password_hash VARCHAR(255) NOT NULL, expires_at DATETIME NOT NULL, used_at DATETIME DEFAULT NULL, created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP, INDEX(user_id), FOREIGN KEY(user_id) REFERENCES users(id) ON DELETE CASCADE);
CREATE TABLE categories (id CHAR(36) PRIMARY KEY, slug VARCHAR(100) NOT NULL UNIQUE, name JSON NOT NULL, description JSON NOT NULL, image_url VARCHAR(500) DEFAULT '', order_index INT DEFAULT 0, created_at DATETIME DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE products (id CHAR(36) PRIMARY KEY, slug VARCHAR(200) NOT NULL UNIQUE, name VARCHAR(200) NOT NULL, category_slug VARCHAR(100), price DECIMAL(12,2) NOT NULL, discount_percent INT DEFAULT NULL, rating DECIMAL(2,1) DEFAULT NULL, short_description JSON NOT NULL, description JSON NOT NULL, stock INT NOT NULL DEFAULT 0, featured BOOLEAN DEFAULT FALSE, status ENUM('active','draft') DEFAULT 'draft', created_at DATETIME DEFAULT CURRENT_TIMESTAMP, INDEX(category_slug), FOREIGN KEY(category_slug) REFERENCES categories(slug) ON DELETE SET NULL);
ALTER TABLE products ADD COLUMN IF NOT EXISTS rating DECIMAL(2,1) DEFAULT NULL;
CREATE TABLE product_images (id CHAR(36) PRIMARY KEY, product_id CHAR(36) NOT NULL, url TEXT NOT NULL, position INT DEFAULT 0, FOREIGN KEY(product_id) REFERENCES products(id) ON DELETE CASCADE);
ALTER TABLE product_images MODIFY COLUMN url TEXT NOT NULL;
CREATE TABLE product_specs (id CHAR(36) PRIMARY KEY, product_id CHAR(36) NOT NULL, label JSON NOT NULL, value VARCHAR(255) NOT NULL, position INT DEFAULT 0, FOREIGN KEY(product_id) REFERENCES products(id) ON DELETE CASCADE);
CREATE TABLE vouchers (id CHAR(36) PRIMARY KEY, code VARCHAR(50) NOT NULL UNIQUE, type ENUM('percentage','fixed') NOT NULL, value DECIMAL(12,2) NOT NULL, min_purchase DECIMAL(12,2) DEFAULT 0, max_discount DECIMAL(12,2) DEFAULT NULL, start_date DATE NOT NULL, expiry_date DATE NOT NULL, usage_limit INT DEFAULT NULL, used_count INT DEFAULT 0, active BOOLEAN DEFAULT TRUE, eligible_categories JSON DEFAULT NULL);
CREATE TABLE orders (id CHAR(36) PRIMARY KEY, number VARCHAR(30) NOT NULL UNIQUE, user_id CHAR(36) DEFAULT NULL, customer_name VARCHAR(120) NOT NULL, customer_email VARCHAR(255) NOT NULL, customer_phone VARCHAR(30) DEFAULT '', address TEXT NOT NULL, notes TEXT, subtotal DECIMAL(12,2) NOT NULL, product_discount DECIMAL(12,2) DEFAULT 0, voucher_code VARCHAR(50) DEFAULT NULL, voucher_discount DECIMAL(12,2) DEFAULT 0, shipping_fee DECIMAL(12,2) DEFAULT 0, total DECIMAL(12,2) NOT NULL, status ENUM('pending','processing','shipped','completed','cancelled') DEFAULT 'pending', payment_method VARCHAR(30) DEFAULT 'bank_transfer', payment_status ENUM('waiting','submitted','approved','rejected') DEFAULT 'waiting', payment_note TEXT, payment_reviewed_at DATETIME DEFAULT NULL, created_at DATETIME DEFAULT CURRENT_TIMESTAMP, updated_at DATETIME DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP, INDEX(customer_email), INDEX(status), FOREIGN KEY(user_id) REFERENCES users(id) ON DELETE SET NULL, FOREIGN KEY(voucher_code) REFERENCES vouchers(code) ON DELETE SET NULL);
CREATE TABLE order_items (id CHAR(36) PRIMARY KEY, order_id CHAR(36) NOT NULL, product_id CHAR(36) DEFAULT NULL, slug VARCHAR(200) NOT NULL, name VARCHAR(200) NOT NULL, image_url VARCHAR(500) DEFAULT '', quantity INT NOT NULL, unit_price DECIMAL(12,2) NOT NULL, subtotal DECIMAL(12,2) NOT NULL, FOREIGN KEY(order_id) REFERENCES orders(id) ON DELETE CASCADE, FOREIGN KEY(product_id) REFERENCES products(id) ON DELETE SET NULL);
CREATE TABLE payment_proofs (id CHAR(36) PRIMARY KEY, order_id CHAR(36) NOT NULL, original_name VARCHAR(255), mime_type VARCHAR(100), file_path VARCHAR(500) NOT NULL, file_size INT, status ENUM('submitted','approved','rejected') DEFAULT 'submitted', reviewer_note TEXT, submitted_at DATETIME DEFAULT CURRENT_TIMESTAMP, reviewed_at DATETIME DEFAULT NULL, FOREIGN KEY(order_id) REFERENCES orders(id) ON DELETE CASCADE);
CREATE TABLE services (id CHAR(36) PRIMARY KEY, slug VARCHAR(100) NOT NULL UNIQUE, index_label VARCHAR(10), title JSON NOT NULL, description JSON NOT NULL, price_from DECIMAL(12,2) DEFAULT 0, image_url VARCHAR(500) DEFAULT '');
ALTER TABLE services ADD COLUMN IF NOT EXISTS image_url VARCHAR(500) DEFAULT '';
CREATE TABLE service_deliverables (id CHAR(36) PRIMARY KEY, service_id CHAR(36) NOT NULL, label JSON NOT NULL, position INT DEFAULT 0, FOREIGN KEY(service_id) REFERENCES services(id) ON DELETE CASCADE);
CREATE TABLE portfolio_projects (id CHAR(36) PRIMARY KEY, slug VARCHAR(200) UNIQUE, title VARCHAR(200), client VARCHAR(120), category JSON, year INT, cover_url VARCHAR(500), description JSON, service_tags JSON);
CREATE TABLE portfolio_images (id CHAR(36) PRIMARY KEY, project_id CHAR(36) NOT NULL, url VARCHAR(500), position INT DEFAULT 0, FOREIGN KEY(project_id) REFERENCES portfolio_projects(id) ON DELETE CASCADE);
CREATE TABLE testimonials (id CHAR(36) PRIMARY KEY, quote JSON NOT NULL, name VARCHAR(120), role JSON, avatar VARCHAR(500), position INT DEFAULT 0);
CREATE TABLE promotions (id CHAR(36) PRIMARY KEY, placement ENUM('announcement','home-banner') NOT NULL, title JSON NOT NULL, code VARCHAR(50), active BOOLEAN DEFAULT TRUE);
CREATE TABLE site_content (id INT PRIMARY KEY DEFAULT 1, content JSON NOT NULL);
CREATE TABLE payment_accounts (id CHAR(36) PRIMARY KEY, bank_name VARCHAR(100) NOT NULL, account_name VARCHAR(120) NOT NULL, account_number VARCHAR(50) NOT NULL, active BOOLEAN DEFAULT TRUE);
